    cf_name_map = {cf.name.lower(): cf for cf in CustomFactor.query.all()}

    error_counts = {}
    valid_counts = {}
    with open('bulk_tier3_360_per_region.csv', 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for i, row in enumerate(reader):
            obj, errs = _process_row(row, 1, fac_name_map, fac_id_map, cf_name_map, compute_emissions, API_FACTORS, 'auto')
            fac = row.get('facility_name', 'unknown')
            if errs:
                error_counts[errs[0]] = error_counts.get(errs[0], 0) + 1
            else:
                valid_counts[fac] = valid_counts.get(fac, 0) + 1
    print('Valid counts by facility:', valid_counts)
    print('Error counts:', error_counts)
